import React from 'react';
import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        {/* Dein eigener Header-Inhalt */}
        <h1>Willkommen auf meiner Webseite!</h1>
      </header>
      <main>
        <section>
          <h2>Über mich</h2>
          <p>Ich bin ein Medieninformatik-Student seit 2023.</p>
          <p>Kenntnisse in Java, TypeScript, HTML, CSS, C#</p>
          <p>
            Mein GitHub-Profil:{" "}
            <a
              className="App-link"
              href="https://github.com/EnesYildiz24?tab=repositories"
              target="_blank"
              rel="noopener noreferrer"
            >
              Meine GitHub Repositories
            </a>
          </p>
        </section>
      </main>
    </div>
  );
}

export default App;
